SELECT COUNT(*)
FROM book_comment c
JOIN book_comment p
  ON p.id = c.parent_comment_id
 AND p.book_id = #{bookId}
 AND p.parent_comment_id IS NULL
WHERE c.book_id = #{bookId}
  AND c.parent_comment_id = #{commentId}
  AND c.status = 0

SELECT COUNT(*)
FROM book_comment
WHERE id = #{commentId}
  AND book_id = #{bookId}
  AND parent_comment_id IS NULL

SELECT COUNT(*)
FROM book_comment
WHERE id = #{commentId}
  AND book_id = #{bookId}
  AND parent_comment_id IS NULL
  AND status = 0

mapper.update:
UPDATE book_comment
SET status = 1,
    update_time = NOW()
WHERE id = #{commentId}
  AND user_id = #{userId}
  AND status = 0
